function.arguments:
{"sql":"WITH team_totals AS (
  SELECT TeamName, SUM(Points) AS total_points
  FROM results
  WHERE season = 2024 AND session = 'R' AND Status IN ('Finished', 'Lapped')
  GROUP BY TeamName
),
max_total AS (
  SELECT MAX(total_points) AS max_points FROM team_totals
)
SELECT TeamName, total_points
FROM team_totals, max_total
WHERE total_points = max_points;
"}

{"sql":"WITH team_totals AS (
  SELECT TeamName, SUM(Points) AS total_points
  FROM results
  WHERE season = 2024 AND session = 'R' AND Status IN ('Finished', 'Lapped')
  GROUP BY TeamName
),
max_total AS (
  SELECT MAX(total_points) AS max_points FROM team_totals
)
SELECT TeamName, total_points
FROM team_totals, max_total
WHERE total_points = max_points;
"}

